<?php

declare(strict_types=1);

namespace MadeByClowd\Documentable\Doctor;

use Illuminate\Support\Facades\Http;
use Throwable;

/**
 * Checks that a presigned PUT URL generated by Presigner can accept an HTTP upload.
 *
 * @internal
 */
final class PresignedPutProbe implements Probe
{
    public function name(): string
    {
        return 'PresignedPut';
    }

    public function run(DoctorContext $context): ProbeResult
    {
        $key = $context->scratchPrefix.'presigned-put-test.txt';

        try {
            $signed = $context->presigner->upload($context->disk, $key, now()->addMinutes(5));

            $response = Http::withHeaders($signed['headers'])
                ->withBody('doctor-presigned-put-content', 'application/octet-stream')
                ->put($signed['url']);

            if (! $response->successful()) {
                return ProbeResult::fail(
                    $this->name(),
                    "Presigned PUT returned HTTP {$response->status()}: {$response->body()}",
                    'Verify that presign_endpoint is reachable, CORS allows PUT requests, and bucket permissions include s3:PutObject.'
                );
            }

            return ProbeResult::pass($this->name(), 'Presigned PUT upload succeeded over HTTP.');
        } catch (Throwable $e) {
            return ProbeResult::fail(
                $this->name(),
                "Presigned PUT failed: {$e->getMessage()}",
                'Ensure the presigned URL endpoint is accessible from the client and credentials are valid.'
            );
        }
    }
}
